/**
 * In-browser Java engine (CheerpJ). Wraps a classic Blob worker in the shared
 * long-lived-worker manager so the WASM JVM + javac stay warm between runs.
 *
 * Cold (first) run downloads the CheerpJ runtime and javac; warm runs are
 * typically a few seconds. The warm timeout is raised above the default because
 * each run re-invokes javac, which is slower than an interpreter.
 */
import type { ExecRequest, ExecResult } from "../types";
import { createLocalEngine } from "./localWorkerEngine";

/**
 * Classic worker served from public/javaWorker.js (generated by
 * scripts/gen-java-worker.mjs). CheerpJ 4.3 requires a classic worker with a
 * real HTTP URL — see scripts/javaWorker.template.js for why.
 */
function makeWorker(): Worker {
  return new Worker(`${import.meta.env.BASE_URL}javaWorker.js`);
}

const engine = createLocalEngine({
  name: "Java",
  makeWorker,
  coldRunTimeoutMs: 300_000,
  warmRunTimeoutMs: 60_000,
});

export function executeJava(req: ExecRequest, signal?: AbortSignal): Promise<ExecResult> {
  return engine(req, signal);
}
